{"command": "$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.IO.Compression.FileSystem
$files = @(
 'LLM-tmp\01-策划案\《檐下千秋》游戏策划案.docx',
 'LLM-tmp\02-叙事脚本\《檐下千秋》章节叙事脚本.docx',
 'LLM-tmp\《檐下千秋》AI产出汇总-2026-08-28.docx'
)
foreach ($f in $files) {
  $full = Join-Path $PWD $f
  if (-not (Test-Path $full)) { "MISSING: $f"; continue }
  $zip = [System.IO.Compression.ZipFile]::OpenRead($full)
  $hit = $false
  foreach ($e in $zip.Entries) {
    if ($e.FullName -like 'word/*.xml') {
      $sr = New-Object System.IO.StreamReader($e.Open())
      $xml = $sr.ReadToEnd(); $sr.Close()
      if ($xml -match '金山' -or $xml -match '飛鳥山' -or $xml -match '飞鸟山') { $hit = $true; "HIT in $f :: $($e.FullName)" }
    }
  }
  if (-not $hit) { "no hit: $f" }
  $zip.Dispose()
}", "description": "Search docx files for 金山"}

