{"command": "$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.IO.Compression.FileSystem
Get-ChildItem -Recurse -File -Force 'Task01' -Filter '*.docx' | ForEach-Object {
  $zip = [System.IO.Compression.ZipFile]::OpenRead($_.FullName)
  $hits = @()
  foreach ($e in $zip.Entries) {
    if ($e.FullName -like 'word/document.xml') {
      $sr = New-Object System.IO.StreamReader($e.Open()); $xml = $sr.ReadToEnd(); $sr.Close()
      foreach ($m in [regex]::Matches($xml, '.{0,40}金山.{0,40}')) { $hits += $m.Value }
    }
  }
  $zip.Dispose()
  if ($hits.Count -gt 0) { "HIT $($_.Name)"; $hits | ForEach-Object { "   $_" } } else { "no hit: $($_.Name)" }
}", "description": "Search Task01 docx files for 金山"}

