{"command": "$needle = [System.Text.Encoding]::UTF8.GetBytes('金山')
"needle bytes: " + ($needle -join ',')
$roots = @('LLM-tmp','Task01','Task02','Task03','docs','LLM_Temp','Official_Document','输出','output','Art_Material','dist')
Get-ChildItem -Recurse -File -Force $roots -ErrorAction SilentlyContinue | Where-Object { $_.Length -lt 20MB } | ForEach-Object {
  try {
    $bytes = [System.IO.File]::ReadAllBytes($_.FullName)
    for ($i=0; $i -le $bytes.Length - $needle.Length; $i++) {
      if ($bytes[$i] -eq $needle[0] -and $bytes[$i+1] -eq $needle[1] -and $bytes[$i+2] -eq $needle[2] -and $bytes[$i+3] -eq $needle[3] -and $bytes[$i+4] -eq $needle[4] -and $bytes[$i+5] -eq $needle[5]) {
        "HIT: " + $_.FullName.Replace($PWD.Path+'\','')
        break
      }
    }
  } catch {}
}", "description": "Byte-level search for 金山 across project files"}

