{"command": "Add-Type -AssemblyName System.IO.Compression.FileSystem
function Get-DocxText($path) {
  $zip = [System.IO.Compression.ZipFile]::OpenRead($path)
  $e = $zip.Entries | Where-Object { $_.FullName -eq 'word/document.xml' }
  $sr = New-Object System.IO.StreamReader($e.Open()); $xml = $sr.ReadToEnd(); $sr.Close(); $zip.Dispose()
  $xml = $xml -replace '</w:p>', "`n"
  $xml = $xml -replace '<[^>]+>', ''
  return $xml
}
foreach ($f in @('LLM-tmp\01-策划案\《檐下千秋》游戏策划案.docx','LLM-tmp\02-叙事脚本\《檐下千秋》章节叙事脚本.docx')) {
  $t = Get-DocxText (Join-Path $PWD $f)
  "===== $f ====="
  "长度: " + $t.Length
  foreach ($k in '结局设计','三种终章','五章十任务','飞鸟山','通关呓语','千层墨','拓印图') {
    "  " + $k + " : " + ([regex]::Matches($t, [regex]::Escape($k)).Count)
  }
}", "description": "Compare docx mirrors against markdown"}

